originalCss:
:root {
    --bg: #07111e;
    --bg2: #0d1b2e;
    --card: #0f1f35;
    --card2: #132640;
    --line: #1f3555;
    --accent: #7c9eff;
    --accent2: #5eead4;
    --text: #e6edf7;
    --text-dim: #c7d6ec;
    --text-faint: #9cb0cf;
    --warn: #fbbf24;
    --ok: #86efac;
    --sb: 288px;
}
* {
    box-sizing: border-box;
}
html {
    scroll-behavior: smooth;
    overflow-x: hidden;
}
body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family:
        'Noto Sans JP', 'Hiragino Kaku Gothic ProN', 'Yu Gothic', Meiryo, sans-serif;
    font-size: 16px;
    line-height: 1.85;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}
.layout {
    display: block;
}
.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    width: var(--sb);
    background: #050d17;
    border-right: 1px solid var(--line);
    overflow-y: auto;
    padding: 20px 14px 40px;
    z-index: 30;
}
.sb-brand {
    display: flex;
    flex-direction: column;
    gap: 4px;
    padding: 6px 10px 16px;
    border-bottom: 1px solid var(--line);
    margin-bottom: 12px;
}
.sb-badge {
    font-weight: 800;
    font-size: 15px;
    color: #fff;
    letter-spacing: 0.02em;
}
.sb-sub {
    font-size: 12px;
    color: var(--text-faint);
}
.sb-list {
    list-style: none;
    margin: 0;
    padding: 0;
}
.sb-list a {
    display: block;
    padding: 7px 10px;
    margin: 1px 0;
    border-radius: 8px;
    color: var(--text-dim);
    text-decoration: none;
    font-size: 13px;
    line-height: 1.5;
    border-left: 2px solid transparent;
}
.sb-list a:hover {
    background: var(--bg2);
    color: #fff;
}
.sb-list a.active {
    background: rgba(124, 158, 255, 0.14);
    color: #fff;
    border-left-color: var(--accent);
    font-weight: 700;
}
.sidebar-toggle {
    display: none;
    position: fixed;
    top: 12px;
    left: 12px;
    z-index: 40;
    background: var(--card2);
    color: #fff;
    border: 1px solid var(--line);
    border-radius: 10px;
    padding: 8px 14px;
    font: inherit;
    font-size: 14px;
    cursor: pointer;
}
.main {
    margin-left: var(--sb);
    padding: 36px 44px 80px;
}
.hero {
    position: relative;
    overflow: hidden;
    background: linear-gradient(180deg, var(--card) 0, var(--bg2) 100%);
    border: 1px solid var(--line);
    border-radius: 18px;
    padding: 34px 36px 28px;
    margin-bottom: 32px;
}
.hero::before {
    content: '';
    position: absolute;
    top: -120px;
    right: -80px;
    width: 420px;
    height: 420px;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.28), transparent 65%);
    pointer-events: none;
}
.eyebrow {
    display: inline-block;
    font-size: 11.5px;
    font-weight: 700;
    letter-spacing: 0.12em;
    color: var(--accent);
    background: rgba(124, 158, 255, 0.12);
    border: 1px solid rgba(124, 158, 255, 0.35);
    border-radius: 999px;
    padding: 4px 14px;
    margin-bottom: 14px;
}
.hero-title {
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    line-height: 1.35;
    margin: 0 0 10px;
}
.hero-sub {
    margin: 0 0 22px;
    color: var(--text-dim);
    font-size: 15px;
}
.hero-meta {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    border-top: 1px solid var(--line);
    padding-top: 18px;
    gap: 16px 28px;
}
.hm-item {
    padding: 2px 0 2px 14px;
    border-left: 2px solid var(--line);
    min-width: 0;
}
.hm-label {
    font-size: 11px;
    letter-spacing: 0.08em;
    color: var(--text-faint);
    text-transform: uppercase;
    margin-bottom: 2px;
}
.hm-value {
    font-size: 14.5px;
    color: var(--text);
    line-height: 1.6;
}
.main h2 {
    font-size: 24px;
    font-weight: 800;
    color: #fff;
    margin: 56px 0 18px;
    padding: 10px 0 10px 14px;
    border-left: 4px solid var(--accent);
    background: linear-gradient(90deg, rgba(124, 158, 255, 0.12), transparent 60%);
    border-radius: 0 8px 8px 0;
    scroll-margin-top: 20px;
}
.main h3 {
    font-size: 19px;
    font-weight: 700;
    color: #dbe6ff;
    margin: 34px 0 12px;
    scroll-margin-top: 20px;
}
.main h3::before {
    content: '';
    display: inline-block;
    width: 8px;
    height: 8px;
    border-radius: 2px;
    background: var(--accent2);
    margin-right: 10px;
    vertical-align: middle;
}
.anchor {
    opacity: 0;
    margin-left: 8px;
    color: var(--text-faint);
    text-decoration: none;
    font-weight: 400;
}
h2:hover .anchor,
h3:hover .anchor {
    opacity: 0.8;
}
.main p {
    margin: 0 0 14px;
    color: var(--text);
}
.main ul,
.main ol {
    padding-left: 1.6em;
    margin: 0 0 16px;
}
.main li {
    margin: 4px 0;
}
.main strong {
    color: #fff;
}
.main a {
    color: var(--accent);
    text-decoration: underline;
    text-underline-offset: 3px;
    word-break: break-all;
}
.main hr {
    border: 0;
    border-top: 1px solid var(--line);
    margin: 40px 0;
}
code:not(pre code) {
    font-family: 'JetBrains Mono', ui-monospace, Menlo, Consolas, monospace;
    font-size: 0.9em;
    background: var(--card2);
    border: 1px solid var(--line);
    border-radius: 6px;
    padding: 1px 6px;
    color: #cfe0ff;
    overflow-wrap: break-word;
}
.table-scroll {
    overflow-x: auto;
    margin: 0 0 22px;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--card);
}
table {
    border-collapse: collapse;
    width: 100%;
    min-width: 560px;
    font-size: 14.5px;
}
th {
    background: var(--card2);
    color: #fff;
    text-align: left;
    font-weight: 700;
    padding: 10px 14px;
    border-bottom: 1px solid var(--line);
    white-space: nowrap;
}
td {
    padding: 9px 14px;
    border-bottom: 1px solid #162a47;
    vertical-align: top;
    color: var(--text);
    line-height: 1.7;
}
tr:last-child td {
    border-bottom: 0;
}
tbody tr:hover td {
    background: rgba(124, 158, 255, 0.06);
}
td a {
    word-break: break-all;
}
.callout {
    border: 1px solid var(--line);
    border-left-width: 4px;
    border-radius: 10px;
    padding: 12px 18px 6px;
    margin: 0 0 20px;
    background: var(--card);
}
.callout-title {
    font-weight: 800;
    font-size: 14px;
    margin-bottom: 6px;
    display: flex;
    align-items: center;
    gap: 8px;
    color: #fff;
}
.callout-icon {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    border-radius: 6px;
    font-size: 13px;
    background: rgba(255, 255, 255, 0.08);
}
.callout-body p {
    margin: 0 0 8px;
    color: var(--text);
}
.callout-note {
    border-left-color: var(--accent);
}
.callout-warn {
    border-left-color: var(--warn);
    background: rgba(251, 191, 36, 0.06);
}
.callout-warn .callout-icon {
    color: var(--warn);
}
.callout-example {
    border-left-color: var(--accent2);
    background: rgba(94, 234, 212, 0.05);
}
.callout-example .callout-icon {
    color: var(--accent2);
}
.callout-source {
    padding: 8px 16px 2px;
    border-left-color: var(--text-faint);
    font-size: 14px;
}
.callout-source .callout-body p {
    color: var(--text-dim);
}
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    background: var(--bg2);
    border: 1px solid var(--line);
    border-radius: 14px;
    padding: 20px 14px;
    margin: 0 0 24px;
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: none;
    flex-shrink: 0;
}
.mermaid-diagram p {
    color: inherit !important;
    margin: 0;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.checklist-card {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 14px;
    padding: 16px 20px 8px;
    margin: 0 0 24px;
}
.checklist-progress {
    display: flex;
    align-items: center;
    gap: 14px;
    margin-bottom: 12px;
}
.cp-label {
    font-weight: 700;
    font-size: 13px;
    color: var(--text-dim);
    white-space: nowrap;
}
.cp-bar {
    flex: 1;
    height: 8px;
    background: var(--bg);
    border-radius: 99px;
    overflow: hidden;
    border: 1px solid var(--line);
}
.cp-fill {
    height: 100%;
    width: 0;
    background: linear-gradient(90deg, var(--accent), var(--accent2));
    transition: width 0.25s;
}
.cp-count {
    font-size: 13px;
    color: var(--text-dim);
    font-variant-numeric: tabular-nums;
    white-space: nowrap;
}
ul.task-list {
    list-style: none;
    padding-left: 0;
    margin: 0 0 12px;
    display: grid;
    gap: 8px;
}
ul.task-list li {
    margin: 0;
    padding: 0;
}
ul.task-list label {
    display: flex;
    align-items: flex-start;
    gap: 14px;
    padding: 11px 16px;
    border: 1px solid var(--line);
    border-radius: 12px;
    background: var(--bg2);
    cursor: pointer;
    transition:
        border-color 0.15s,
        background 0.15s,
        transform 0.15s;
    line-height: 1.7;
}
ul.task-list label:hover {
    border-color: rgba(124, 158, 255, 0.6);
    background: #10223a;
}
ul.task-list li.done label {
    border-color: rgba(94, 234, 212, 0.45);
    background: linear-gradient(
        90deg,
        rgba(94, 234, 212, 0.1),
        rgba(124, 158, 255, 0.05)
    );
    color: var(--text-dim);
}
ul.task-list input[type='checkbox'] {
    -webkit-appearance: none;
    appearance: none;
    position: relative;
    flex: 0 0 24px;
    width: 24px;
    height: 24px;
    margin: 2px 0 0;
    border: 2px solid #4a6490;
    border-radius: 7px;
    background: var(--bg);
    cursor: pointer;
    transition:
        background 0.15s,
        border-color 0.15s,
        box-shadow 0.15s;
}
ul.task-list input[type='checkbox']:hover {
    border-color: var(--accent);
}
ul.task-list input[type='checkbox']:focus-visible {
    outline: none;
    box-shadow: 0 0 0 3px rgba(124, 158, 255, 0.45);
}
ul.task-list input[type='checkbox']:checked {
    background: linear-gradient(135deg, var(--accent), var(--accent2));
    border-color: transparent;
}
ul.task-list input[type='checkbox']::after {
    content: '';
    position: absolute;
    left: 7px;
    top: 2px;
    width: 6px;
    height: 12px;
    border: solid #07111e;
    border-width: 0 3px 3px 0;
    border-radius: 1px;
    transform: rotate(45deg) scale(0);
    transition: transform 0.15s;
}
ul.task-list input[type='checkbox']:checked::after {
    transform: rotate(45deg) scale(1);
}
ul.task-list li.done label span.txt {
    opacity: 0.85;
}
.cp-reset {
    background: none;
    border: 1px solid var(--line);
    color: var(--text-dim);
    border-radius: 8px;
    padding: 3px 10px;
    font: inherit;
    font-size: 12px;
    cursor: pointer;
}
.cp-reset:hover {
    border-color: var(--accent);
    color: #fff;
}
.cp-done {
    color: var(--accent2);
    font-weight: 700;
}
.page-footer {
    margin-top: 60px;
    padding-top: 20px;
    border-top: 1px solid var(--line);
    color: var(--text-faint);
    font-size: 13px;
    text-align: center;
}
@media (max-width: 1200px) {
    .hero-meta {
        grid-template-columns: repeat(2, minmax(0, 1fr));
    }
}
@media (max-width: 960px) {
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.25s;
        box-shadow: 0 0 40px rgba(0, 0, 0, 0.6);
    }
    .sidebar.open {
        transform: none;
    }
    .sidebar-toggle {
        display: block;
    }
    .main {
        margin-left: 0;
        padding: 64px 16px 60px;
    }
    .hero {
        padding: 24px 20px;
    }
    .hero-title {
        font-size: 23px;
    }
    .hero-meta {
        grid-template-columns: 1fr;
    }
    .main h2 {
        font-size: 20px;
    }
}
